BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats15-q01', '多変量解析',
   'テストの点数を「勉強時間」1つだけから予測するのが単回帰、「勉強時間」と「睡眠時間」など複数の変数から予測するのが重回帰だった。この重回帰のように、複数の変数を同時に扱って全体の構造やつながりを調べる統計の手法をまとめて何と呼ぶ？',
   NULL::text,
   '["多変量解析（複数の変数を同時に扱い、変数どうしの関係や全体の構造を調べる統計の総称）", "単変量解析（1つの変数だけを取り出し、その分布やばらつきを調べる統計の総称）", "重回帰分析（複数の説明変数から1つの目的変数の値を予測する、多変量解析の中の1手法）", "記述統計（平均や分散など、データの基本的な特徴を数字でまとめる統計の総称）"]',
   0, '[0]', 'single',
   '{"asked": "複数の変数を同時に扱う統計の手法全体を指す、大きなくくりの名前。", "point": "「変数が2つ以上、同時に登場する」統計はすべて多変量解析の仲間。重回帰はその中の1つの手法にすぎない。", "kid": "多変量解析は、身長・体重・年齢のようにいろいろな種類のデータ(変数)を、バラバラにではなく一緒くたに見て、変数どうしのつながりや全体の姿をつかもうとする統計のグループ名。", "eg": "健康診断の結果表を1項目ずつ(身長だけ、体重だけ)見るのが単変量。身長・体重・血圧・年齢を全部並べて「どの数値どうしが一緒に動いているか」を見るのが多変量解析。見る範囲の広さが違う。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">変数を1つだけ使うか、複数同時に使うか</text>\n<text x=\"85\" y=\"36\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">単回帰（変数1つ）</text>\n<rect x=\"45\" y=\"46\" width=\"80\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"85\" y=\"58\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">勉強時間</text>\n<text x=\"85\" y=\"80\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">↓</text>\n<rect x=\"45\" y=\"88\" width=\"80\" height=\"18\" fill=\"#3b82f6\"/><text x=\"85\" y=\"100\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">点数</text>\n<line x1=\"170\" y1=\"26\" x2=\"170\" y2=\"120\" stroke=\"#2a2f3f\"/>\n<text x=\"255\" y=\"36\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">多変量解析（変数が複数）</text>\n<rect x=\"185\" y=\"44\" width=\"60\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"215\" y=\"54\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">勉強時間</text>\n<rect x=\"185\" y=\"60\" width=\"60\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"215\" y=\"70\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">睡眠時間</text>\n<rect x=\"185\" y=\"76\" width=\"60\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"215\" y=\"86\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">演習量</text>\n<line x1=\"245\" y1=\"51\" x2=\"285\" y2=\"94\" stroke=\"#60a5fa\" stroke-width=\"1\"/>\n<line x1=\"245\" y1=\"67\" x2=\"285\" y2=\"97\" stroke=\"#60a5fa\" stroke-width=\"1\"/>\n<line x1=\"245\" y1=\"83\" x2=\"285\" y2=\"100\" stroke=\"#60a5fa\" stroke-width=\"1\"/>\n<rect x=\"255\" y=\"94\" width=\"60\" height=\"18\" fill=\"#3b82f6\"/><text x=\"285\" y=\"106\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">点数</text>\n<text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">重回帰のように、複数の変数を同時に扱う統計の総称</text>\n</svg>", "terms": [["多変量解析", "複数の変数を同時に扱い、変数どうしの関係や全体の構造を調べる統計の総称"], ["重回帰分析", "複数の説明変数から1つの目的変数の値を予測する手法。多変量解析の中の1つ"]], "think": "なぜ重回帰が「多変量解析の一例」であって「多変量解析そのもの」ではないのかがカギ。重回帰は、複数の変数(説明変数)を使って1つの目的変数を予測する、というやり方の1つにすぎない。この先に出てくる主成分分析(変数をまとめる)や判別分析(グループを当てる)、クラスター分析(グループに分ける)も、どれも「複数の変数を同時に扱う」という共通点を持つ、別のやり方。この「複数の変数を同時に扱う」という共通点をくくった呼び名が多変量解析であり、重回帰はその中の1手法という関係になる。", "vs": "単変量解析(平均・分散のように1つの変数だけを見る)と混同しないこと。変数が1つか、2つ以上を同時に扱うかで呼び名が分かれる。", "why_asked": "この先に出てくる主成分分析・因子分析・判別分析・クラスター分析は、名前も見た目もバラバラに見えるが、すべて多変量解析という同じ屋根の下にある手法。まず全体の呼び名を知っておかないと、個々の手法がどう位置づくのか見えなくなる。", "usecase": "顧客データのように、年齢・購入金額・来店回数など多くの項目が同時に手元にあるとき、その関係や構造をまとめて調べたい場面全般で登場する統計の枠組み。", "opt": ["正解。重回帰のように複数の変数を同時に扱い、関係や構造を調べる統計をまとめて多変量解析と呼ぶ。", "単変量解析は1つの変数だけを取り出して調べる統計で、複数の変数を同時に扱う今回の話とは逆の範囲を指す。", "重回帰分析は多変量解析というくくりの中の1つの手法の名前。「まとめて何と呼ぶか」という、より大きなくくりを聞かれている今回の問いの答えとしては範囲が狭すぎる。", "記述統計は平均や分散などデータの基本的な特徴をまとめる統計の総称で、変数どうしの関係を調べる多変量解析とは指している範囲が異なる。"]}'),

  ('stats15-q02', '多変量解析',
   '50人分の体格データに、身長・体重・胸囲・座高など10個の測定項目がある。これら10個の変数を、元のばらつき(情報)をなるべく残したまま、2〜3個の合成変数にまとめたい。使う手法はどれ？',
   NULL::text,
   '["主成分分析（PCA）（元の変数の情報をなるべく保ったまま、少数の合成変数（主成分）にまとめる手法）", "因子分析（観測できる複数の変数の背後にある、直接は測れないいくつかの共通の要因を推定する手法）", "クラスター分析（似た特徴を持つデータどうしを、あらかじめ決めた基準でグループに自動でまとめる手法）", "重回帰分析（複数の説明変数の値を組み合わせて、1つの目的変数の値を予測して求める手法）"]',
   0, '[0]', 'single',
   '{"asked": "多くの変数を、情報をなるべく保ったまま少数の変数にまとめる手法の名前。", "point": "「情報をなるべく保つ」とは、元のデータのばらつき(分散)をなるべく多く合成変数に残すこと。", "kid": "主成分分析は、たくさんある変数を全部バラバラに見るのをやめて、「一番効率よく特徴をとらえられる、少ない数の新しい物差し(主成分)」に作り替える手法。身長や体重など10個の物差しを、2〜3個の物差しに減らしても、データの個性(ばらつき)はなるべく失わないようにする。", "eg": "旅行の荷造りで例えると、Tシャツを5枚全部持っていく代わりに、色や柄がなるべくかぶらない2〜3枚に厳選するようなもの。枚数(変数の数)は減らしても、持っていく服のバリエーション(情報)はなるべく残す。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">10個の測定項目を、情報(ばらつき)を保ったまま圧縮する</text>\n<rect x=\"20\" y=\"34\" width=\"20\" height=\"60\" fill=\"#2a2f3f\"/><rect x=\"44\" y=\"34\" width=\"20\" height=\"60\" fill=\"#2a2f3f\"/><rect x=\"68\" y=\"34\" width=\"20\" height=\"60\" fill=\"#2a2f3f\"/><rect x=\"92\" y=\"34\" width=\"20\" height=\"60\" fill=\"#2a2f3f\"/><rect x=\"116\" y=\"34\" width=\"20\" height=\"60\" fill=\"#2a2f3f\"/>\n<text x=\"78\" y=\"106\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">身長・体重・胸囲など10項目</text>\n<text x=\"160\" y=\"66\" fill=\"#8892a4\" font-size=\"13\" text-anchor=\"middle\">→</text>\n<rect x=\"215\" y=\"44\" width=\"34\" height=\"40\" fill=\"#3b82f6\"/><rect x=\"257\" y=\"52\" width=\"34\" height=\"24\" fill=\"#60a5fa\"/>\n<text x=\"253\" y=\"106\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">2〜3個の合成変数(主成分)</text>\n<text x=\"170\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">個数は減るが、ばらつき(情報)はなるべく残す</text>\n</svg>", "terms": [["主成分分析(PCA)", "複数の変数を、情報(ばらつき)をなるべく保ったまま少数の合成変数(主成分)にまとめる手法"], ["情報の量", "ここでは「データがどれだけばらついているか」、つまり分散の大きさのこと"]], "think": "なぜ「情報を保つ」ことと「ばらつきを保つ」ことが同じ意味になるのかがカギ。もし10人全員の身長がまったく同じ170cmだったら、身長という変数は誰の個性も表せておらず、情報としての価値がない。逆に身長が150cmから190cmまでばらついていれば、その人がどんな体格かを言い当てる手がかりになる。つまり「ばらついている」ことこそが「その変数が人によって違いを説明できている」ことの証拠であり、情報の中身にあたる。だから主成分分析は、変数の数を減らすときに、なるべくばらつき(情報)が失われない方向を選んで合成変数を作る。", "vs": "「変数を減らす」という結果だけを見るとクラスター分析(データをグループに分ける)と混同しやすいが、主成分分析はあくまで変数(物差し)そのものを作り替える手法で、人やデータをグループ分けするわけではない。この違いは後の設問でさらに扱う。", "why_asked": "主成分分析は「なぜ2乗するのか」のような単発の計算ではなく、「情報=ばらつき」という発想そのものが土台になっている。この発想を先に押さえておかないと、次に出てくる「一番ばらついている方向を選ぶ」という主成分の決め方が、ただの丸暗記になってしまう。", "usecase": "アンケートの多数の質問項目を少数の指標に要約する、顧客の購買データを少数の特徴にまとめて分析しやすくする、画像や音声の大量のデータ量を圧縮する、といった場面で使われる。", "opt": ["正解。10個の変数を、ばらつき(情報)をなるべく保ったまま少数の合成変数にまとめるのが主成分分析(PCA)。", "因子分析は、観測できる変数の背後にある直接測れない要因を推定する手法。変数を要約すること自体が目的の今回とは、目的の向きが異なる（詳しくは後の設問で扱う）。", "クラスター分析は、データ(人)を似たものどうしのグループに分ける手法。変数(物差し)そのものを少なくする今回の目的とは対象が異なる。", "重回帰分析は、複数の説明変数から1つの目的変数の値を予測する手法。変数どうしをまとめて少数の合成変数にする今回の目的とは異なる。"]}'),

  ('stats15-q03', '多変量解析',
   '2つの変数の散布図に主成分分析を行うと、まずデータが一番大きくばらついている方向に1本目の軸(第一主成分)を引く。2本目の軸(第二主成分)は、どのような向きに選ぶ？',
   NULL::text,
   '["第一主成分と直交（90度に交わる）する方向のうち、残りのばらつきが一番大きい方向", "第一主成分とほぼ同じ方向のままで、データのばらつきが2番目に大きくなる向きを選ぶ", "身長や体重など、元の変数のうちどれか1つの軸を、そのまま第二主成分として使う", "第一主成分の向きとは無関係に、データの散らばりを無視してランダムに選んだ方向"]',
   0, '[0]', 'single',
   '{"asked": "第一主成分を決めたあと、第二主成分の向きをどう選ぶか。", "point": "第二主成分は、第一主成分と直交(90度)する方向の中で、残りのばらつきが一番大きい向きに選ぶ。", "kid": "第一主成分は「データが一番ぐんと伸びている方向」に引く軸。第二主成分は、その軸と直角に交わる向きの中で、まだ説明できていない残りのばらつきを一番よく拾える向きに引く、2本目の軸。", "eg": "楕円形のグラウンドを思い浮かべると分かりやすい。グラウンドの一番長い方向(縦)に1本目の物差し(第一主成分)を当て、それと直角に交わる一番短い方向(横)に2本目の物差し(第二主成分)を当てる。斜めに物差しを当てても、縦と横の広がりをきれいに測れない。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">一番ばらついている方向から順に軸を選ぶ</text>\n<circle cx=\"80\" cy=\"70\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"100\" cy=\"80\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"120\" cy=\"92\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"140\" cy=\"60\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"160\" cy=\"72\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"180\" cy=\"84\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"200\" cy=\"98\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"150\" cy=\"105\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"130\" cy=\"112\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"170\" cy=\"50\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"190\" cy=\"62\" r=\"2.4\" fill=\"#8892a4\"/><circle cx=\"110\" cy=\"66\" r=\"2.4\" fill=\"#8892a4\"/>\n<line x1=\"65\" y1=\"112\" x2=\"212\" y2=\"52\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<text x=\"215\" y=\"48\" fill=\"#3b82f6\" font-size=\"9.5\" font-weight=\"600\">第一主成分</text>\n<line x1=\"127.9\" y1=\"56.1\" x2=\"149.1\" y2=\"107.9\" stroke=\"#60a5fa\" stroke-width=\"1.6\" stroke-dasharray=\"4 2\"/>\n<text x=\"138.5\" y=\"45\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">第二主成分</text>\n<text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">第二主成分は第一主成分と直交(90度)する方向で</text>\n<text x=\"170\" y=\"144\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">残りのばらつきが一番大きい向きを選ぶ</text>\n</svg>", "terms": [["第一主成分", "データが一番大きくばらついている方向に引く、1本目の合成変数の軸"], ["直交", "2本の線が90度に交わっていること。第二主成分は第一主成分と必ず直交する向きに選ばれる"]], "think": "なぜ第二主成分をわざわざ直交する方向に限定するのかがカギ。もし第二主成分を第一主成分に近い向きに選んでしまうと、2本目の軸が1本目とほとんど同じ情報を測ることになり、変数を2つに増やした意味が薄れてしまう(重複した情報を2回数えるだけになる)。直交する方向に限定することで、第二主成分は第一主成分がまだ拾いきれていない、別の方向のばらつきだけを新しく説明できる。こうして重複を避けながら、限られた本数の軸で元の情報をなるべく多く拾い集めていく。", "vs": "「ばらつきが2番目に大きい方向」というだけでは第二主成分の説明として不十分。第一主成分のすぐ近くの向きにも2番目に大きいばらつきがあるかもしれないが、それは直交していなければ第二主成分には選ばれない。直交という条件が必ずセットになる。", "why_asked": "「主成分は分散が大きい順に選ぶ」という部分だけを覚えると、なぜ2本目・3本目の軸が互いに直交するのかが抜け落ちる。直交条件を知っていないと、主成分どうしが独立した(重複しない)情報を持つ、という主成分分析の重要な性質が理解できない。", "usecase": "アンケートの回答パターンを2つの軸(例えば「満足度の高さ」と「回答のばらつきの大きさ」)に要約して散布図に描き、回答者の傾向を視覚的につかむような場面で、第一・第二主成分の組み合わせが使われる。", "opt": ["正解。第二主成分は第一主成分と直交する方向の中で、残りのばらつきが一番大きい向きに選ばれる。", "第一主成分とほぼ同じ方向を選ぶと、2本目の軸が1本目とほぼ同じ情報を測ることになり、新しい情報を拾えなくなる。第二主成分は直交する向きに選ばれる。", "元の変数の軸(身長や体重そのもの)をそのまま使うのではなく、データのばらつき方に応じて新しく引き直す軸が主成分。元の軸とは向きが一致するとは限らない。", "ランダムに選ぶのではなく、第一主成分と直交する方向の中で、残りのばらつきが一番大きくなるように計算して選ばれる。"]}'),

  ('stats15-q04', '多変量解析',
   '国語・英語・社会・数学・理科の5教科のテストの点数には、「文系科目が得意かどうか」「理系科目が得意かどうか」という、テストでは直接測れない共通の要因が背後にあると考えられる。このように、観測できる複数の変数の背後にある、直接は測れない共通の要因を推定する手法を何と呼ぶ？',
   NULL::text,
   '["因子分析（観測できる複数の変数の背後にある、直接は測れない共通の要因を推定する手法）", "主成分分析（元の変数の情報をなるべく保ったまま、少数の合成変数にまとめる手法）", "重回帰分析（複数の説明変数から1つの目的変数の値を予測する手法）", "判別分析（あらかじめ分かっているグループを使って、新しいデータがどちらに属するか予測する手法）"]',
   0, '[0]', 'single',
   '{"asked": "見える複数の変数の背後にある、見えない共通の要因を推定する手法の名前。", "point": "「点数(見える)を、背後の因子(見えない)が動かしている」と考えて、その因子を逆算するのが因子分析。", "kid": "因子分析は、テストの点数のように実際に測れる数字の裏に、「文系の力」「理系の力」のような、直接は測れない隠れた力があると考えて、その隠れた力がどれくらいかを点数から推理する手法。", "eg": "5教科の点数は、体温計の目盛りのようなもの。体温計そのもの(点数)は見えるが、体の中の熱の原因(因子、たとえば風邪)は直接は見えない。因子分析は、いくつかの体温計(教科の点数)の動き方から、背後にある見えない原因(因子)を推理する作業に近い。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">見えない共通の要因が、見える点数を動かしていると考える</text>\n<ellipse cx=\"90\" cy=\"46\" rx=\"46\" ry=\"16\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<text x=\"90\" y=\"50\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">文系の力（因子）</text>\n<ellipse cx=\"250\" cy=\"46\" rx=\"46\" ry=\"16\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<text x=\"250\" y=\"50\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">理系の力（因子）</text>\n<rect x=\"24\" y=\"92\" width=\"42\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"45\" y=\"104\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">国語</text>\n<rect x=\"70\" y=\"92\" width=\"42\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"91\" y=\"104\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">英語</text>\n<rect x=\"116\" y=\"92\" width=\"42\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"137\" y=\"104\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">社会</text>\n<rect x=\"205\" y=\"92\" width=\"42\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"226\" y=\"104\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">数学</text>\n<rect x=\"251\" y=\"92\" width=\"42\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"272\" y=\"104\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">理科</text>\n<line x1=\"75\" y1=\"60\" x2=\"45\" y2=\"90\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n<line x1=\"90\" y1=\"62\" x2=\"91\" y2=\"90\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n<line x1=\"105\" y1=\"60\" x2=\"137\" y2=\"90\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n<line x1=\"235\" y1=\"60\" x2=\"226\" y2=\"90\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n<line x1=\"250\" y1=\"62\" x2=\"272\" y2=\"90\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n<text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">因子（見えない）→ 各教科の点数（見える）へ、矢印が伸びる向き</text>\n</svg>", "terms": [["因子", "観測できる複数の変数に共通して影響を与えている、直接は測れない要因"], ["因子分析", "観測できる変数の背後にある、直接は測れない共通の因子を推定する手法"]], "think": "なぜ「点数から因子を逆算する」という発想が必要なのかがカギ。国語・英語・社会の点数がいつも一緒に高かったり低かったりする人が多いなら、その裏に「文系の力」という共通の何かが働いていると考えるのが自然。しかし「文系の力」そのものはテストで直接測れる数字ではない。そこで因子分析は、目に見える点数どうしの連動のしかたを手がかりに、目に見えない共通の因子がどれくらい働いているかを、逆向きに推定する。この「見える結果から見えない原因を推理する」という向きが、因子分析の考え方の中心になる。", "vs": "「複数の変数を扱う」という点は主成分分析と似ているが、因子分析は変数の背後にある原因を探ることが目的で、主成分分析は変数をなるべく情報を保ったまま要約することが目的。この違いは次の設問で詳しく比べる。", "why_asked": "似た響きの主成分分析と混同されやすいが、目的も矢印の向きも異なる別の手法。因子分析を知らないまま先に進むと、次に出てくる「主成分分析と因子分析の違い」が理解できなくなる。", "usecase": "性格診断のアンケートで、多数の質問項目の背後にある「外向性」「協調性」のような性格の因子を推定する、マーケティング調査で複数の商品評価の背後にある「価格への敏感さ」のような隠れた消費者心理を推定する、といった場面で使われる。", "opt": ["正解。国語・英語・社会や数学・理科の点数の背後にある、直接は測れない「文系の力」「理系の力」のような共通の要因を推定するのが因子分析。", "主成分分析は、変数の情報をなるべく保ったまま少数の合成変数にまとめる手法。変数の背後にある原因を探る今回の目的とは、矢印の向きが逆になる（詳しくは次の設問で扱う）。", "重回帰分析は、複数の説明変数から1つの目的変数の値を予測する手法。目に見えない共通の要因を推定する今回の目的とは異なる。", "判別分析は、あらかじめ分かっているグループ分けを使って新しいデータの所属を予測する手法。これは後の設問で扱う、また別の目的の手法。"]}'),

  ('stats15-q05', '多変量解析',
   '主成分分析と因子分析は、どちらも複数の変数を同時に扱うが、目的とねらいが違う。正しい対比はどれ？',
   NULL::text,
   '["主成分分析はデータを少ない変数に要約するのが目的、因子分析は変数の背後にある原因（共通因子）を探るのが目的", "主成分分析はデータの背後にある原因をひたすら探ることが目的で、因子分析はデータを少ない変数へ要約することが目的", "主成分分析も因子分析も、どちらも複数の変数をなるべく少ない数の変数へと要約することだけが共通の目的", "主成分分析も因子分析も、どちらも変数の背後にある共通の原因をひたすら探ることだけが共通の目的である"]',
   0, '[0]', 'single',
   '{"asked": "主成分分析と因子分析、それぞれの目的の違い。", "point": "矢印の向きで見分ける。変数から合成変数へ向かうのが主成分分析(要約)、因子から変数へ向かうのが因子分析(原因探し)。", "kid": "主成分分析は「たくさんの変数をぎゅっとまとめて、少ない数で代表させたい」ときに使う。因子分析は「点数の裏に、何か共通の隠れた原因があるはずだ、それを探り当てたい」ときに使う。似ているようで、見ている向きが逆。", "eg": "主成分分析は、いろんな味の飲み物を「甘さ」「炭酸の強さ」というごく少数の代表指標にまとめて棚に並べ直す作業。因子分析は、売れ行きのデータから「この地域は暑がりの人が多いのでは」という、直接は見えない背景の理由を推理する作業。まとめるのか、理由を探るのかが違う。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">矢印の向きで見る、2つの手法の目的の違い</text>\n<text x=\"85\" y=\"34\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">主成分分析</text>\n<rect x=\"45\" y=\"44\" width=\"24\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"73\" y=\"44\" width=\"24\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"101\" y=\"44\" width=\"24\" height=\"14\" fill=\"#2a2f3f\"/>\n<line x1=\"57\" y1=\"58\" x2=\"85\" y2=\"82\" stroke=\"#3b82f6\" stroke-width=\"1\"/>\n<line x1=\"85\" y1=\"58\" x2=\"85\" y2=\"82\" stroke=\"#3b82f6\" stroke-width=\"1\"/>\n<line x1=\"113\" y1=\"58\" x2=\"85\" y2=\"82\" stroke=\"#3b82f6\" stroke-width=\"1\"/>\n<rect x=\"63\" y=\"82\" width=\"44\" height=\"16\" fill=\"#3b82f6\"/><text x=\"85\" y=\"94\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">合成変数</text>\n<text x=\"85\" y=\"112\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">変数→まとめる</text>\n<text x=\"85\" y=\"124\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">目的：要約</text>\n<line x1=\"170\" y1=\"22\" x2=\"170\" y2=\"128\" stroke=\"#2a2f3f\"/>\n<text x=\"255\" y=\"34\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">因子分析</text>\n<rect x=\"233\" y=\"44\" width=\"44\" height=\"16\" fill=\"#60a5fa\"/><text x=\"255\" y=\"56\" fill=\"#141720\" font-size=\"7.5\" text-anchor=\"middle\">因子</text>\n<line x1=\"243\" y1=\"60\" x2=\"215\" y2=\"82\" stroke=\"#60a5fa\" stroke-width=\"1\"/>\n<line x1=\"255\" y1=\"60\" x2=\"255\" y2=\"82\" stroke=\"#60a5fa\" stroke-width=\"1\"/>\n<line x1=\"267\" y1=\"60\" x2=\"295\" y2=\"82\" stroke=\"#60a5fa\" stroke-width=\"1\"/>\n<rect x=\"195\" y=\"82\" width=\"24\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"243\" y=\"82\" width=\"24\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"283\" y=\"82\" width=\"24\" height=\"14\" fill=\"#2a2f3f\"/>\n<text x=\"255\" y=\"112\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">因子→変数を動かす</text>\n<text x=\"255\" y=\"124\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">目的：原因を探る</text>\n</svg>", "terms": [["主成分分析", "複数の変数の情報をなるべく保ったまま、少数の合成変数に要約する手法"], ["因子分析", "観測できる複数の変数の背後にある、直接は測れない共通の因子を推定する手法"]], "think": "なぜ同じ「複数の変数を扱う手法」なのに目的が正反対になるのかがカギ。主成分分析は、手元にある変数(身長・体重など)を出発点にして、そこから情報をなるべく保ちながら少ない数の合成変数を作り出す。つまり矢印は「変数→合成変数」の向き。因子分析は逆に、手元にある変数(点数)を「結果」とみなし、その結果を生み出した見えない原因(因子)を出発点として想定し、そこから変数へ矢印が伸びていると考える。同じように複数の変数を扱っていても、矢印がどちら向きかで、要約したいのか(主成分分析)、原因を探りたいのか(因子分析)という目的が入れ替わる。", "vs": "「変数の数を減らす」という結果だけを見ると2つは似て見えるが、主成分分析の合成変数はあくまで元の変数の「まとめ役」であり、因子分析の因子は元の変数を生み出す「原因」だと考えられている。この立ち位置の違いが目的の違いに直結する。", "why_asked": "見た目や計算の手順が似ているため、実務でもどちらを使うべきか迷いやすい組み合わせ。目的の違い(要約したいのか、原因を探りたいのか)を先に決めてから手法を選ばないと、分析結果の解釈を誤る。", "usecase": "多数のセンサーの計測値を少数の指標にまとめてダッシュボードで見たいなら主成分分析、アンケートの背後にある心理的な傾向(因子)を知りたいなら因子分析、というように目的に応じて使い分ける。", "opt": ["正解。主成分分析は変数をなるべく情報を保ったまま少ない数に要約するのが目的、因子分析は変数の背後にある共通の原因(因子)を探るのが目的。", "主成分分析と因子分析の目的が入れ替わっている。要約が目的なのは主成分分析、原因を探るのが目的なのは因子分析。", "因子分析は要約ではなく、変数の背後にある原因を探ることが目的。「どちらも要約が目的」とまとめてしまうと、因子分析の目的を取り違えることになる。", "主成分分析は原因探しではなく、変数を要約することが目的。「どちらも原因を探ることが目的」とまとめてしまうと、主成分分析の目的を取り違えることになる。"]}'),

  ('stats15-q06', '多変量解析',
   'すでに合格・不合格が分かっている過去の受験者100人分の、試験の点数や面接評価のデータがある。これを使って、新しい受験者のデータから合格になりそうか不合格になりそうかを予測するルールを作る手法はどれ？',
   NULL::text,
   '["判別分析（あらかじめ分かっているグループ分けを使って、新しいデータがどちらのグループに属するかを予測する手法）", "回帰分析（複数の説明変数の値を組み合わせて、連続した数値をとる目的変数の値を予測して求める手法）", "クラスター分析（グループ分けがまだ何も分かっていない状態のデータを、似たものどうしで自動的にグループにまとめる手法）", "主成分分析（複数の変数が持つ情報をなるべく多く保ったまま、少数の合成変数（主成分）にまとめる手法）"]',
   0, '[0]', 'single',
   '{"asked": "すでに分かっているグループ分けを手がかりに、新しいデータの所属を予測するときの手法の名前。", "point": "「答え(合格・不合格)がすでに分かっているデータ」を手本にして、新しいデータの所属を予測するのが判別分析。", "kid": "判別分析は、「この人は合格・この人は不合格」という正解がすでに分かっている過去のデータを先生役にして、新しく来た人のデータから「合格側か、不合格側か」を言い当てるルールを作る手法。", "eg": "健康診断で例えると、過去に「健康」「要注意」と診断済みの1000人分のデータをもとに、新しく来た人の検査値だけから「この人はどちらに近いか」を判定するようなもの。すでに答え合わせ済みのデータを手本にする点がポイント。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">分かっている合否の分かれ目から、新しい人の合否を当てる</text>\n<circle cx=\"70\" cy=\"50\" r=\"3\" fill=\"#6ab08d\"/><circle cx=\"90\" cy=\"42\" r=\"3\" fill=\"#6ab08d\"/><circle cx=\"100\" cy=\"60\" r=\"3\" fill=\"#6ab08d\"/><circle cx=\"75\" cy=\"68\" r=\"3\" fill=\"#6ab08d\"/><circle cx=\"55\" cy=\"62\" r=\"3\" fill=\"#6ab08d\"/>\n<circle cx=\"220\" cy=\"90\" r=\"3\" fill=\"#c47070\"/><circle cx=\"245\" cy=\"98\" r=\"3\" fill=\"#c47070\"/><circle cx=\"260\" cy=\"80\" r=\"3\" fill=\"#c47070\"/><circle cx=\"230\" cy=\"105\" r=\"3\" fill=\"#c47070\"/><circle cx=\"255\" cy=\"108\" r=\"3\" fill=\"#c47070\"/>\n<line x1=\"20\" y1=\"112\" x2=\"300\" y2=\"30\" stroke=\"#3b82f6\" stroke-width=\"1.6\" stroke-dasharray=\"5 3\"/>\n<text x=\"250\" y=\"60\" fill=\"#3b82f6\" font-size=\"9\" font-weight=\"600\" text-anchor=\"middle\">判別の境界線</text>\n<circle cx=\"150\" cy=\"60\" r=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.8\"/>\n<text x=\"150\" y=\"46\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\">新しい受験者</text>\n<text x=\"65\" y=\"85\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">合格した人</text>\n<text x=\"245\" y=\"122\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">不合格だった人</text>\n<text x=\"170\" y=\"134\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">境界線のどちら側かで、新しい人の所属を予測する</text>\n</svg>", "terms": [["判別分析", "あらかじめ分かっているグループ分けを使って、新しいデータがどちらのグループに属するかを予測する手法"], ["境界線", "判別分析でグループどうしを分ける、データの上に引かれる線。新しいデータがどちら側にあるかで所属を判定する"]], "think": "なぜ「あらかじめ分かっている」ことが判別分析の前提になるのかがカギ。判別分析がルールを作れるのは、過去の受験者について「実際に合格したか不合格だったか」という正解が先にデータに付いているから。この正解付きのデータから、点数や面接評価がどのあたりの値なら合格側・不合格側になりやすいかという境界線を計算で求める。境界線ができれば、正解がまだ分からない新しい受験者についても、その境界線のどちら側に位置するかを見るだけで所属を予測できる。正解が最初から分かっているデータを手本にする、という前提が無いと、この境界線を引くことができない。", "vs": "似たように「グループに分ける」という言葉が出てくるクラスター分析と混同しやすいが、判別分析は最初からグループ(合格・不合格)が分かっているデータを手本に予測ルールを作るのに対し、クラスター分析はそもそもグループ分け自体が分かっていないデータを、似たものどうしでグループ化する。この違いは次のクラスター分析の設問でさらに扱う。", "why_asked": "「グループを扱う」という点でクラスター分析と混同されやすい代表的な組み合わせ。あらかじめ正解(グループ)が分かっているかどうかという前提の違いを知らないと、どちらの手法を使うべきか判断できない。", "usecase": "過去の顧客データ(継続・解約)から新しい顧客が解約しそうかを予測する、過去の検査データ(良品・不良品)から新しい製品が不良品かどうかを判定する、といった場面で使われる。", "opt": ["正解。合格・不合格というあらかじめ分かっているグループ分けを手本に、新しい受験者がどちらに属するかを予測するルールを作るのが判別分析。", "回帰分析は、点数のような連続した数値そのものを予測する手法。合格・不合格という2択のグループを予測する今回の目的とは、予測したいものの種類が異なる。", "クラスター分析は、グループ分け自体がまだ分かっていないデータを、似たものどうしでグループにまとめる手法。合格・不合格という正解がすでに分かっている今回の状況とは前提が異なる。", "主成分分析は、変数の情報をなるべく保ったまま少数の合成変数にまとめる手法。新しいデータの所属を予測したい今回の目的とは異なる。"]}'),

  ('stats15-q07', '多変量解析',
   'K-meansは、あらかじめ「いくつのグループに分けるか」を決めてから、データをそのグループの数に分ける手法だった。これに対し、似ているものどうしを1つずつペアにしてまとめていき、最後に全体が1つになるまで木のような構造でまとめていく手法を何と呼ぶ？',
   NULL::text,
   '["階層型クラスタリング（似たものどうしを順にまとめていき、木構造（デンドログラム）で表すクラスター分析の手法）", "K-means（あらかじめグループの数をいくつと決めてから、データをそのグループの数に分けるクラスター分析の手法）", "判別分析（あらかじめ分かっているグループ分けを使って、新しいデータがどちらのグループに属するかを予測する手法）", "主成分分析（複数の変数が持つ情報をなるべく多く保ったまま、少数の合成変数（主成分）にまとめる手法）"]',
   0, '[0]', 'single',
   '{"asked": "似たものどうしを順にペアにしてまとめ、木構造で表すクラスター分析の手法の名前。", "point": "K-meansは先にグループ数を決めてから分ける。階層型クラスタリングは近いものから順に合体させ、木構造(デンドログラム)を作る。", "kid": "階層型クラスタリングは、まず一番似ている2人(または2つのデータ)を1組にする。次に、残りの中で一番似ている組をまた1組にする。これを繰り返して、最後には全員が1つの大きな木にまとまるまで続ける、グループのまとめ方。", "eg": "部活動のトーナメント表を逆から作るようなもの。まず一番仲の良い2人組を作り、次にその2人組どうしや、まだ組んでいない人どうしで一番近いところをまた組ませ、これを繰り返して最後は全員が1つの大きな組織図につながる。", "viz": "<svg viewBox=\"0 0 340 142\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">似ているものから順にペアを作り、木のようにまとめる</text>\n<circle cx=\"30\" cy=\"112\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"55\" cy=\"112\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"90\" cy=\"112\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"115\" cy=\"112\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"150\" cy=\"112\" r=\"3\" fill=\"#8892a4\"/>\n<line x1=\"30\" y1=\"109\" x2=\"30\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><line x1=\"55\" y1=\"109\" x2=\"55\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><line x1=\"30\" y1=\"90\" x2=\"55\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/>\n<line x1=\"90\" y1=\"109\" x2=\"90\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><line x1=\"115\" y1=\"109\" x2=\"115\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><line x1=\"90\" y1=\"90\" x2=\"115\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/>\n<line x1=\"42.5\" y1=\"90\" x2=\"42.5\" y2=\"70\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><line x1=\"102.5\" y1=\"90\" x2=\"102.5\" y2=\"70\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><line x1=\"42.5\" y1=\"70\" x2=\"102.5\" y2=\"70\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/>\n<line x1=\"150\" y1=\"109\" x2=\"150\" y2=\"50\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/>\n<line x1=\"72.5\" y1=\"70\" x2=\"72.5\" y2=\"50\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><line x1=\"72.5\" y1=\"50\" x2=\"150\" y2=\"50\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/>\n<text x=\"111\" y=\"40\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">最後は全体が1つの木につながる</text>\n<line x1=\"180\" y1=\"26\" x2=\"180\" y2=\"128\" stroke=\"#2a2f3f\"/>\n<text x=\"255\" y=\"40\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">（比較）K-means</text>\n<circle cx=\"230\" cy=\"70\" r=\"18\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>\n<circle cx=\"222\" cy=\"65\" r=\"2.4\" fill=\"#c9a04a\"/><circle cx=\"235\" cy=\"72\" r=\"2.4\" fill=\"#c9a04a\"/><circle cx=\"228\" cy=\"78\" r=\"2.4\" fill=\"#c9a04a\"/>\n<circle cx=\"285\" cy=\"95\" r=\"18\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>\n<circle cx=\"278\" cy=\"90\" r=\"2.4\" fill=\"#c9a04a\"/><circle cx=\"290\" cy=\"98\" r=\"2.4\" fill=\"#c9a04a\"/><circle cx=\"282\" cy=\"102\" r=\"2.4\" fill=\"#c9a04a\"/>\n<text x=\"255\" y=\"126\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">先にグループ数を決めて分ける</text>\n</svg>", "terms": [["階層型クラスタリング", "似たものどうしを順に1組ずつまとめていき、木構造(デンドログラム)で表すクラスター分析の手法"], ["デンドログラム", "階層型クラスタリングの結果を、木のような枝分かれの図で表したもの"]], "think": "なぜ階層型クラスタリングでは先にグループ数を決めなくてよいのかがカギ。K-meansは「3グループに分ける」のように先に数を決めてから、データをその数に振り分ける計算をする。一方、階層型クラスタリングは数を決めず、ただ「今一番似ている2つをくっつける」という操作を、全部が1つにまとまるまでひたすら繰り返すだけでよい。結果として木構造(デンドログラム)ができあがるので、あとから木のどの高さで切るかを選べば、2グループにも5グループにも自由に分け直せる。グループ数を先に決めなくてよいという柔軟さが、この手法の特徴になる。", "vs": "K-meansと階層型クラスタリングは、どちらも「似たものをグループにまとめる」クラスター分析の仲間だが、K-meansは先にグループ数を決めて振り分ける方式、階層型クラスタリングは近いものから順に合体させて木を作る方式、という手順が異なる。", "why_asked": "クラスター分析にはK-meansだけでなく、木構造で結果を表す階層型クラスタリングという別のやり方もあることを知らないと、「グループの数をあらかじめ決められない」場面で選択肢を見落としてしまう。", "usecase": "生物の種の系統関係を木構造で表す、顧客のグループをいくつに分けるべきか事前に決めずに探索的に調べる、といった場面で、木構造のどの高さで切るかを見ながらグループ数を後から決めたいときに使われる。", "opt": ["正解。似たものどうしを順にペアにしてまとめていき、最後に全体が1つの木構造(デンドログラム)になるまで続けるのが階層型クラスタリング。", "K-meansは、あらかじめグループの数を決めてからデータを振り分ける手法。木構造を作りながら順にまとめていく今回の手法とは手順が異なる。", "判別分析は、あらかじめ分かっているグループ分けを使って新しいデータの所属を予測する手法。グループ分け自体が分かっていないデータを対象にする今回の話とは前提が異なる。", "主成分分析は、変数の情報をなるべく保ったまま少数の合成変数にまとめる手法。データをグループにまとめる今回の目的とは対象が異なる。"]}'),

  ('stats15-q08', '多変量解析',
   '主成分分析とクラスター分析は、どちらも複数の変数を扱うが、それぞれ何を減らしたり分けたりするのが目的か。正しい対比はどれ？',
   NULL::text,
   '["主成分分析は変数の数を減らすこと（次元削減）が目的、クラスター分析はデータをグループに分けることが目的", "主成分分析はデータをいくつかのグループに分けることが目的で、クラスター分析は変数の数を減らすことが目的", "主成分分析もクラスター分析も、どちらも変数の数をなるべく減らすことだけが共通の目的である", "主成分分析もクラスター分析も、どちらもデータをいくつかのグループに分けることだけが共通の目的"]',
   0, '[0]', 'single',
   '{"asked": "主成分分析とクラスター分析、それぞれが「減らす・分ける」対象の違い。", "point": "主成分分析が減らすのは「変数(物差し)の数」。クラスター分析が分けるのは「データ(人やモノ)の集まり」。", "kid": "主成分分析は、身長・体重・座高など「測るための物差し」の数を減らして少なくする。クラスター分析は、物差しの数はそのままで、測られた「人やモノそのもの」を似たグループに仕分けする。減らす・分ける対象が違う。", "eg": "クラスの整理整頓に例えると、主成分分析は「体育の道具、音楽の道具、図工の道具…」とバラバラにあった持ち物の分類項目(物差し)を、「運動系」「文化系」という少ない分類にまとめ直す作業。クラスター分析は、分類項目の数はそのままに、生徒たち(データ)を仲の良いグループに分けていく作業。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">「変数を減らす」のか「データを分ける」のか</text>\n<text x=\"85\" y=\"34\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">主成分分析</text>\n<rect x=\"45\" y=\"44\" width=\"18\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"67\" y=\"44\" width=\"18\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"89\" y=\"44\" width=\"18\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"111\" y=\"44\" width=\"18\" height=\"14\" fill=\"#2a2f3f\"/>\n<text x=\"85\" y=\"70\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">↓</text>\n<rect x=\"63\" y=\"78\" width=\"44\" height=\"16\" fill=\"#3b82f6\"/><text x=\"85\" y=\"90\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">少数の軸</text>\n<text x=\"85\" y=\"112\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">目的：次元削減</text>\n<text x=\"85\" y=\"124\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">（変数の数を減らす）</text>\n<line x1=\"170\" y1=\"22\" x2=\"170\" y2=\"128\" stroke=\"#2a2f3f\"/>\n<text x=\"255\" y=\"34\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">クラスター分析</text>\n<circle cx=\"225\" cy=\"55\" r=\"3\" fill=\"#6ab08d\"/><circle cx=\"235\" cy=\"62\" r=\"3\" fill=\"#6ab08d\"/><circle cx=\"222\" cy=\"65\" r=\"3\" fill=\"#6ab08d\"/>\n<circle cx=\"270\" cy=\"80\" r=\"3\" fill=\"#c9a04a\"/><circle cx=\"280\" cy=\"70\" r=\"3\" fill=\"#c9a04a\"/><circle cx=\"278\" cy=\"88\" r=\"3\" fill=\"#c9a04a\"/>\n<text x=\"255\" y=\"112\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">目的：グループ分け</text>\n<text x=\"255\" y=\"124\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">（データを分ける）</text>\n</svg>", "terms": [["次元削減", "変数(物差し)の数を減らすこと。主成分分析の目的"], ["グループ分け（クラスタリング）", "データ(人やモノ)を似たものどうしのグループに分けること。クラスター分析の目的"]], "think": "なぜ同じ「複数の変数を扱う手法」なのに、減らす対象が変数とデータで違ってくるのかがカギ。主成分分析は、身長・体重・座高のように「測る側の項目(変数)」が多すぎて扱いにくいときに、その項目自体を少ない合成変数にまとめて、扱いやすくすることを目指す。クラスター分析は、項目(変数)の数はそのままにしておき、代わりに「測られた側(人やモノ)」を、値の近さをもとにいくつかのグループに仕分けることを目指す。「物差しを減らしたいのか」「測られた対象をグループに分けたいのか」という、着目する対象の違いが、そのまま目的の違いになっている。", "vs": "「複数の変数を使って何かをまとめる」という表面的な共通点だけで同じ手法だと思い込まないこと。主成分分析は変数側の要約、クラスター分析はデータ側の仕分けという、まったく別の対象を扱っている。", "why_asked": "主成分分析とクラスター分析は実務でセットで使われることも多いため(先に主成分分析で変数を減らしてから、その少ない軸を使ってクラスター分析でグループ分けする、など)、それぞれが何を目的にした手法かを取り違えると、組み合わせて使う意味も理解できなくなる。", "usecase": "アンケートの多数の質問項目をまず主成分分析で少数の指標に要約し、その指標をもとにクラスター分析で回答者をいくつかのタイプに分ける、というように、目的の異なる2つの手法を続けて使う分析の流れで登場する。", "opt": ["正解。主成分分析は変数の数を減らす次元削減が目的、クラスター分析はデータをグループに分けることが目的。", "主成分分析とクラスター分析の目的が入れ替わっている。変数を減らすのは主成分分析、データをグループに分けるのはクラスター分析。", "クラスター分析は変数を減らすことではなく、データをグループに分けることが目的。「どちらも変数を減らすことが目的」とまとめると、クラスター分析の目的を取り違えることになる。", "主成分分析はデータをグループに分けることではなく、変数の数を減らすことが目的。「どちらもグループに分けることが目的」とまとめると、主成分分析の目的を取り違えることになる。"]}'),

  ('stats15-q09', '多変量解析',
   '身長と体重には強い相関があり、背が高い人ほど体重も重い傾向がある。単純なユークリッド距離は、身長のズレと体重のズレをそのまま組み合わせて「平均からの隔たり」を測る。これに対し、変数どうしの相関やばらつきの違いを考慮して、「本当の近さ・遠さ」を測る距離を何と呼ぶ？',
   NULL::text,
   '["マハラノビス距離（変数どうしの相関やばらつきの違いを考慮して測る、本当の近さ・遠さを表す距離）", "ユークリッド距離（変数どうしの相関をまったく考えに入れず、そのままの座標の差から測るふつうの距離）", "標準偏差（データ全体がどれくらい平均から散らばっているかを表す、ばらつきの大きさを表す値そのもの）", "決定係数（回帰直線がデータの変動をどれくらいよく説明できているかを表す指標そのもの）"]',
   0, '[0]', 'single',
   '{"asked": "変数どうしの相関やばらつきの違いを考慮して測る、「本当の近さ」を表す距離の名前。", "point": "同じ直線距離(ユークリッド距離)でも、データ全体の相関の傾向に沿っているか外れているかで、マハラノビス距離は変わる。", "kid": "マハラノビス距離は、ただの直線の長さ(ユークリッド距離)だけでなく、「そのデータの組み合わせが、全体の傾向からしてありがちか、珍しいか」まで考えに入れて測る距離。傾向どおりの組み合わせは近い扱いに、傾向から外れた組み合わせは遠い扱いになる。", "eg": "身長170cmで体重90kgの人を考える。もし身長170cm・体重65kg前後の人が多い集団なら、この人は身長こそ集団の平均どおりだが、体重だけが平均から大きく重い側にずれた、珍しい組み合わせに見える。単純な直線距離ではそこそこの近さに見えても、集団の傾向(相関)を踏まえると実際にはかなり浮いた存在といえる。マハラノビス距離はこの「浮き具合」まで数字に反映する。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ直線距離でも、相関から外れるほど「本当は遠い」</text>\n<ellipse cx=\"150\" cy=\"85\" rx=\"95\" ry=\"34\" fill=\"#2a2f3f\" opacity=\"0.55\" transform=\"rotate(-28 150 85)\"/>\n<circle cx=\"150\" cy=\"85\" r=\"2.6\" fill=\"#8892a4\"/>\n<text x=\"150\" y=\"72\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">平均</text>\n<circle cx=\"196\" cy=\"60\" r=\"4\" fill=\"#6ab08d\"/>\n<line x1=\"150\" y1=\"85\" x2=\"196\" y2=\"60\" stroke=\"#6ab08d\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>\n<text x=\"222\" y=\"52\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">相関の傾向どおり</text>\n<text x=\"222\" y=\"63\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">→ 実は「近い」</text>\n<circle cx=\"118\" cy=\"42\" r=\"4\" fill=\"#c47070\"/>\n<line x1=\"150\" y1=\"85\" x2=\"118\" y2=\"42\" stroke=\"#c47070\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>\n<text x=\"75\" y=\"34\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">相関の傾向から外れる</text>\n<text x=\"75\" y=\"45\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">→ 実は「遠い」</text>\n<text x=\"170\" y=\"138\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">平均からの直線距離(ユークリッド距離)は2点ともほぼ同じ</text>\n</svg>", "terms": [["マハラノビス距離", "変数どうしの相関やばらつきの違いを考慮して測る、本当の近さ・遠さを表す距離"], ["ユークリッド距離", "変数どうしの相関を考えず、座標の差をそのまま組み合わせて測るふつうの直線距離"]], "think": "なぜ相関を考慮すると距離の測り方が変わるのかがカギ。身長と体重のように強い相関がある2変数では、データの点は斜めに伸びた楕円形の範囲に集まりやすい。この楕円の伸びている方向(相関の傾向どおりの方向)にズレている点は、実は集団の中ではよくある組み合わせで、それほど特別ではない。逆に、楕円の短い方向(相関の傾向から外れる方向)にズレている点は、直線距離としては同じ長さでも、集団の中ではめったに無い珍しい組み合わせになる。マハラノビス距離は、この「楕円のどちら方向にズレているか」を考慮に入れることで、直線距離だけでは見えない「本当の遠さ」を数字にする。", "vs": "ユークリッド距離は変数どうしの相関を一切考えず、座標の差をそのまま組み合わせるだけの、いわば「ものさしで測っただけ」の距離。マハラノビス距離は、そこにデータ全体の広がり方(相関やばらつき)という情報を追加で織り込む点が異なる。", "why_asked": "「距離が近い=似ている」という判断は、判別分析やクラスター分析でも土台になる考え方だが、変数どうしに強い相関があるデータでは、ふつうの直線距離だけで近さを判断すると見誤ることがある。マハラノビス距離は、これまで扱ってきた判別分析やクラスター分析をより正確に行うための、距離の測り方の改良版として位置づけられる。", "usecase": "健康診断で複数の検査値(相関がある値どうし)から見て「その人の値の組み合わせが集団の中でどれくらい珍しいか」を判定する、工場の検査で複数の測定値の組み合わせから異常な製品を見つける、といった場面で使われる。", "opt": ["正解。変数どうしの相関やばらつきの違いを考慮して、直線距離だけでは分からない「本当の近さ・遠さ」を測るのがマハラノビス距離。", "ユークリッド距離は、相関を考えずに座標の差をそのまま組み合わせるふつうの距離。相関を考慮する今回の距離とは対になる、別の測り方。", "標準偏差は、1つの変数がどれくらい平均から散らばっているかを表す値。2つ以上の変数の相関を踏まえて距離を測る今回の話とは、扱う対象の数が異なる。", "決定係数は、回帰直線がデータをどれくらいよく説明できているかを表す指標であり、点と点の間の距離を測るものではない。"]}'),

  ('stats15-q10', '多変量解析',
   'ある会社が1000人の顧客に20項目のアンケートを取った。この20項目の回答から「顧客をいくつかのタイプに分けたい」「20項目を少数の指標に要約したい」と考えている。これらの目的に使う統計の手法をまとめて何と呼ぶ？',
   NULL::text,
   '["多変量解析（アンケートの多数の質問項目の要約や、顧客のグループ分けなど、複数の変数を同時に扱う統計の総称）", "単変量解析（アンケートに含まれる1つの質問項目だけを毎回取り出し、その分布やばらつきだけを調べる統計の総称）", "仮説検定（母集団についての仮説が正しいかどうかを、手元の標本データをもとに判断する統計の手法）", "記述統計（平均や分散など、データの基本的な特徴を1つの項目ずつ数字でまとめる統計の総称）"]',
   0, '[0]', 'single',
   '{"asked": "「要約したい」「グループに分けたい」という複数の目的をまとめて担う、統計の手法全体の名前。", "point": "「変数を要約したい」も「データをグループに分けたい」も、どちらも複数の変数を同時に扱う多変量解析の仕事。", "kid": "20項目のアンケートを1問ずつ見ているだけでは、「顧客のタイプ」も「全体の要約」も見えてこない。20項目を同時に見比べて初めて、「この人たちは似た答え方をしている」「この項目とこの項目はいつも一緒に動いている」ということが分かる。この、複数の変数を同時に見て初めて分かることを扱う統計のグループが多変量解析。", "eg": "20項目のアンケートは、20種類の食材が並んだ食卓のようなもの。1品ずつ味見しても献立全体の傾向は分からないが、全部を並べて見比べると「この組み合わせは和食寄り」「これは洋食寄り」と全体の傾向(要約やタイプ分け)が見えてくる。それが多変量解析。", "viz": "<svg viewBox=\"0 0 340 144\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">複数の変数を同時に扱う目的は、大きく2つに分かれる</text>\n<rect x=\"110\" y=\"26\" width=\"120\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"170\" y=\"40\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">アンケート20項目</text>\n<line x1=\"150\" y1=\"46\" x2=\"100\" y2=\"66\" stroke=\"#8892a4\" stroke-width=\"1.2\"/>\n<line x1=\"190\" y1=\"46\" x2=\"240\" y2=\"66\" stroke=\"#8892a4\" stroke-width=\"1.2\"/>\n<rect x=\"35\" y=\"66\" width=\"130\" height=\"30\" fill=\"#3b82f6\" opacity=\"0.85\"/>\n<text x=\"100\" y=\"80\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">要約する</text>\n<text x=\"100\" y=\"91\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">主成分分析・因子分析</text>\n<rect x=\"175\" y=\"66\" width=\"130\" height=\"30\" fill=\"#60a5fa\" opacity=\"0.85\"/>\n<text x=\"240\" y=\"80\" fill=\"#141720\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">グループに分ける</text>\n<text x=\"240\" y=\"91\" fill=\"#141720\" font-size=\"7.5\" text-anchor=\"middle\">クラスター分析・判別分析</text>\n<text x=\"170\" y=\"118\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">どちらも、変数を1つずつではなく</text>\n<text x=\"170\" y=\"130\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">同時に扱うから見えてくる＝多変量解析</text>\n</svg>", "terms": [["多変量解析", "複数の変数を同時に扱い、要約やグループ分けなど全体の構造を調べる統計の総称"], ["主成分分析・因子分析", "多数の変数を少数の指標に要約したいときに使う、多変量解析の仲間"], ["クラスター分析・判別分析", "データをいくつかのグループに分けたり、所属を予測したりしたいときに使う、多変量解析の仲間"]], "think": "なぜ「要約したい」と「グループに分けたい」という一見別々の目的が、同じ多変量解析という1つのくくりに収まるのかがカギ。この2つの目的はやりたいことこそ違うが、どちらも「変数を1つずつ見るのではなく、複数の変数のつながりを同時に見て初めて答えが出せる」という共通点を持つ。要約したいときは主成分分析や因子分析で変数どうしのつながりを使い、グループに分けたいときはクラスター分析や判別分析で変数の値の近さを使う。目的地は違っても、複数の変数を同時に扱うという入口が同じだから、まとめて多変量解析と呼ばれる。", "vs": "単変量解析(1項目だけの平均やばらつきを見る)では、「20項目を同時に見て初めて分かるタイプ分けや要約」はそもそもできない。複数の変数を同時に扱うかどうかが、多変量解析と単変量解析を分ける境目になる。", "why_asked": "ここまで学んだ主成分分析・因子分析・判別分析・クラスター分析・マハラノビス距離は、名前も手順もバラバラに見えるが、すべて「複数の変数を同時に扱うことで初めて答えが出せる」という共通の入口を持つ、多変量解析という1つの大きな枠組みの中の道具だとまとめて理解しておくと、実務でどの道具を選べばよいか迷ったときの地図になる。", "usecase": "顧客アンケートを分析してマーケティングに活かす、健康診断の複数の検査値から健康状態のタイプを把握する、多数のセンサーのデータから設備の異常を見つける、など、変数が多く手元にあるデータ分析の実務全般で、目的(要約かグループ分けか)に応じてこの中の手法を選んで使う。", "opt": ["正解。要約したいときもグループに分けたいときも、どちらも複数の変数を同時に扱うことで初めて答えが出せる。これをまとめて多変量解析と呼ぶ。", "単変量解析は1つの変数だけを取り出して調べる統計で、複数の変数を同時に見て初めて分かる要約やタイプ分けを担う今回の話とは範囲が異なる。", "仮説検定は、母集団についての仮説が正しいかを標本データから判断する手法。変数どうしのつながりを使って要約やグループ分けをする今回の目的とは異なる。", "記述統計は、平均や分散などデータの基本的な特徴を数字でまとめる統計の総称で、複数の変数を同時に扱う今回の話より扱う範囲が狭い。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
